enum Section { case main }

var dataSource: UICollectionViewDiffableDataSource<Section, User>!

func configureDataSource() {
    let cellReg = UICollectionView.CellRegistration<UICollectionViewListCell, User> {
        cell, indexPath, user in
        var config = cell.defaultContentConfiguration()
        config.text = user.name
        config.secondaryText = user.email
        cell.contentConfiguration = config
    }

    dataSource = UICollectionViewDiffableDataSource(
        collectionView: collectionView
    ) { collectionView, indexPath, user in
        collectionView.dequeueConfiguredReusableCell(
            using: cellReg, for: indexPath, item: user
        )
    }
}

func updateList(with users: [User]) {
    var snapshot = NSDiffableDataSourceSnapshot<Section, User>()
    snapshot.appendSections([.main])
    snapshot.appendItems(users)
    dataSource.apply(snapshot, animatingDifferences: true)
}

struct ImagePicker: UIViewControllerRepresentable {
    @Binding var selectedImage: UIImage?
    @Environment(\.dismiss) var dismiss

    func makeCoordinator() -> Coordinator {
        Coordinator(self)
    }

    func makeUIViewController(context: Context) -> UIImagePickerController {
        let picker = UIImagePickerController()
        picker.delegate = context.coordinator
        return picker
    }

    func updateUIViewController(_ uiVC: UIImagePickerController, context: Context) {}

    class Coordinator: NSObject, UIImagePickerControllerDelegate,
                       UINavigationControllerDelegate {
        let parent: ImagePicker
        init(_ parent: ImagePicker) { self.parent = parent }

        func imagePickerController(_ picker: UIImagePickerController,
            didFinishPickingMediaWithInfo info: [UIImagePickerController.InfoKey: Any]) {
            parent.selectedImage = info[.originalImage] as? UIImage
            parent.dismiss()
        }
    }
}
